contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address player) public {
        require(player != address(0));
        require(player != address(this));
        require(!c.hasPlayerWagered(player));
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        c.play(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted && address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

